style.css:
@-moz-document domain("shein.com") {
/* ===== MAIN BACKGROUND ===== */
html, body {
    background-color: #000000 !important;
    color: #ffb6d9 !important;
}

/* ===== GENERAL TEXT ===== */
* {
    color: #ffb6d9 !important;
    border-color: #ffb6d9 !important;
}

/* ===== HEADER / NAVBAR ===== */
header, .header, .nav, .navigation {
    background-color: #000000 !important;
    border-bottom: 1px solid #ffb6d9 !important;
}

/* ===== PRODUCT CARDS ===== */
[class*="product"], [class*="goods"], [class*="item"] {
    background-color: #0a0a0a !important;
    border: 1px solid #ffb6d9 !important;
}

/* ===== SEARCH BAR ===== */
input, textarea {
    background-color: #111111 !important;
    color: #ffb6d9 !important;
    border: 1px solid #ffb6d9 !important;
}

/* ===== BUTTONS ===== */
button, .btn, [class*="button"] {
    background-color: #ffb6d9 !important;
    color: #000000 !important;
    border: none !important;
}

/* Button hover */
button:hover, .btn:hover, [class*="button"]:hover {
    background-color: #ff8fc5 !important;
    color: #000000 !important;
}

/* ===== LINKS ===== */
a {
    color: #ffb6d9 !important;
}

/* ===== POPUPS / CART / PANELS ===== */
[class*="drawer"], [class*="modal"], [class*="popup"], [class*="cart"] {
    background-color: #0a0a0a !important;
    color: #ffb6d9 !important;
    border: 1px solid #ffb6d9 !important;
}

/* ===== FOOTER ===== */
footer {
    background-color: #000000 !important;
    border-top: 1px solid #ffb6d9 !important;
}

/* ===== SCROLLBAR ===== */
::-webkit-scrollbar {
    width: 10px;
}

::-webkit-scrollbar-track {
    background: #000000;
}

::-webkit-scrollbar-thumb {
    background: #ffb6d9;
    border-radius: 10px;
}
}
